// Runs a batch of asynchronous steps in order.
export interface Step {
  readonly name: string;
  run(): Promise<void>;
}

export type RunResult =
  | { readonly status: "ok"; readonly attempts: number }
  | { readonly status: "failed"; readonly failedStep: string; readonly attempts: number; readonly error: unknown };

export async function runSteps(steps: readonly Step[]): Promise<RunResult> {
  let attempts = 0;
  for (const step of steps) {
    attempts += 1;
    try {
      await step.run();
    } catch (error) {
      return { status: "failed", failedStep: step.name, attempts, error };
    }
  }
  return { status: "ok", attempts };
}

