// Hidden suite for T06, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { RunnerBusyError, createRunner } from "../src/step-runner.ts";
import type { Step, StepEvent } from "../src/step-runner.ts";

function retryable(): Error {
  return Object.assign(new Error("try again"), { retryable: true });
}

/** A step that fails with the given errors, in order, and then succeeds. */
function flaky(name: string, failures: unknown[], log: string[]): Step {
  return {
    name,
    async run() {
      log.push(name);
      const failure = failures.shift();
      if (failure !== undefined) throw failure;
    },
  };
}

function gate(): { promise: Promise<void>; open: () => void } {
  let open: () => void = () => {};
  const promise = new Promise<void>((resolve) => {
    open = () => resolve();
  });
  return { promise, open };
}

const noSleep = async (): Promise<void> => {};

describe("run: order and retries", () => {
  it("runs every step once when all succeed", async () => {
    const log: string[] = [];
    const runner = createRunner({ maxAttempts: 3, sleep: noSleep });
    const result = await runner.run([flaky("a", [], log), flaky("b", [], log), flaky("c", [], log)]);
    expect(result).toEqual({ status: "ok", attempts: 3 });
    expect(log).toEqual(["a", "b", "c"]);
  });

  it("runs steps strictly one after another", async () => {
    const log: string[] = [];
    const slow: Step = {
      name: "slow",
      async run() {
        log.push("slow start");
        await Promise.resolve();
        await Promise.resolve();
        log.push("slow end");
      },
    };
    const runner = createRunner({ maxAttempts: 1, sleep: noSleep });
    await runner.run([slow, flaky("next", [], log)]);
    expect(log).toEqual(["slow start", "slow end", "next"]);
  });

  it("retries a retryable failure up to maxAttempts", async () => {
    const slept: number[] = [];
    const last = retryable();
    const runner = createRunner({ maxAttempts: 3, sleep: async (attempt) => void slept.push(attempt) });
    const result = await runner.run([flaky("a", [retryable(), retryable(), last], [])]);
    expect(result).toEqual({ status: "failed", failedStep: "a", attempts: 3, error: last });
    expect(slept).toEqual([1, 2]);
  });

  it("does not retry errors without the retryable flag", async () => {
    const slept: number[] = [];
    const plain = new Error("bad input");
    const runner = createRunner({ maxAttempts: 3, sleep: async (attempt) => void slept.push(attempt) });
    const result = await runner.run([flaky("a", [plain], [])]);
    expect(result).toEqual({ status: "failed", failedStep: "a", attempts: 1, error: plain });
    expect(slept).toEqual([]);
  });

  it("waits for the backoff before the next attempt", async () => {
    const log: string[] = [];
    const sleep = async (attempt: number): Promise<void> => {
      log.push(`sleep ${attempt}`);
      await Promise.resolve();
      await Promise.resolve();
      log.push("woke");
    };
    const runner = createRunner({ maxAttempts: 2, sleep });
    const result = await runner.run([flaky("a", [retryable()], log)]);
    expect(result).toEqual({ status: "ok", attempts: 2 });
    expect(log).toEqual(["a", "sleep 1", "woke", "a"]);
  });

  it("stops the batch at the first failed step", async () => {
    const log: string[] = [];
    const plain = new Error("broken");
    const runner = createRunner({ maxAttempts: 2, sleep: noSleep });
    const result = await runner.run([flaky("a", [], log), flaky("b", [plain], log), flaky("c", [], log)]);
    expect(result).toEqual({ status: "failed", failedStep: "b", attempts: 2, error: plain });
    expect(log).toEqual(["a", "b"]);
  });

  it("counts attempts across all steps", async () => {
    const runner = createRunner({ maxAttempts: 3, sleep: noSleep });
    const result = await runner.run([flaky("a", [retryable()], []), flaky("b", [], [])]);
    expect(result).toEqual({ status: "ok", attempts: 3 });
  });

  it("reports an event after every attempt", async () => {
    const events: StepEvent[] = [];
    const runner = createRunner({ maxAttempts: 2, sleep: noSleep, onEvent: (event) => events.push(event) });
    await runner.run([flaky("a", [retryable()], []), flaky("b", [new Error("no")], [])]);
    expect(events).toEqual([
      { step: "a", attempt: 1, outcome: "retry" },
      { step: "a", attempt: 2, outcome: "ok" },
      { step: "b", attempt: 1, outcome: "fail" },
    ]);
  });

  it("passes a sleep failure to the caller", async () => {
    const asleep = new Error("clock stopped");
    const runner = createRunner({
      maxAttempts: 2,
      sleep: async () => {
        throw asleep;
      },
    });
    await expect(runner.run([flaky("a", [retryable()], [])])).rejects.toBe(asleep);
  });
});

describe("run: one batch at a time", () => {
  it("refuses a second batch while one is running", async () => {
    const hold = gate();
    const runner = createRunner({ maxAttempts: 1, sleep: noSleep });
    const first = runner.run([{ name: "slow", run: () => hold.promise }]);
    await expect(runner.run([flaky("other", [], [])])).rejects.toBeInstanceOf(RunnerBusyError);
    hold.open();
    expect(await first).toEqual({ status: "ok", attempts: 1 });
  });

  it("accepts a new batch after the previous one finished", async () => {
    const runner = createRunner({ maxAttempts: 1, sleep: noSleep });
    expect(await runner.run([flaky("a", [new Error("no")], [])])).toMatchObject({ status: "failed" });
    expect(await runner.run([flaky("b", [], [])])).toEqual({ status: "ok", attempts: 1 });
  });

  it("accepts a new batch after one ended with an error", async () => {
    const asleep = new Error("clock stopped");
    const runner = createRunner({
      maxAttempts: 2,
      sleep: async () => {
        throw asleep;
      },
    });
    await expect(runner.run([flaky("a", [retryable()], [])])).rejects.toBe(asleep);
    expect(await runner.run([flaky("b", [], [])])).toEqual({ status: "ok", attempts: 1 });
  });

  it("rejects maxAttempts below 1 with a RangeError", () => {
    expect(() => createRunner({ maxAttempts: 0, sleep: noSleep })).toThrow(RangeError);
    expect(() => createRunner({ maxAttempts: 1.5, sleep: noSleep })).toThrow(RangeError);
  });
});
